组合框（Combobox）
一个由 Autocomplete 和 Button 创建的自定义部件。您可以键入一些字符，来获得基于您的输入过滤的结果，或者使用按钮从完整列表中选择。
该输入是从一个已有的 select 元素中读取，传递给带有自定义的 source 选项的 Autocomplete。
这是一个不被支持的不完美的部件。这里纯粹是为了演示 autocomplete 定制功能。如需了解更多有关该部件工作原理的细节，请点击这里查看相关的 jQuery 文章。
<!doctype html>
<html lang="en">
<head>
 <meta charset="utf-8">
 <title>jQuery UI 自动完成（Autocomplete） - 组合框（Combobox）</title>
 <link rel="stylesheet" href="//code.jquery.com/ui/1.10.4/themes/smoothness/jquery-ui.css">
 <script src="//code.jquery.com/jquery-1.9.1.js"></script>
 <script src="//code.jquery.com/ui/1.10.4/jquery-ui.js"></script>
 <link rel="stylesheet" href="http://jqueryui.com/resources/demos/style.css">
 <style>
 .custom-combobox {
 position: relative;
 display: inline-block;
 }
 .custom-combobox-toggle {
 position: absolute;
 top: 0;
 bottom: 0;
 margin-left: -1px;
 padding: 0;
 /* 支持： IE7 */
 *height: 1.7em;
 *top: 0.1em;
 }
 .custom-combobox-input {
 margin: 0;
 padding: 0.3em;
 }
 </style>
 <script>
 (function( $ ) {
 $.widget( "custom.combobox", {
 _create: function() {
 this.wrapper = $( "<span>" )
 .addClass( "custom-combobox" )
 .insertAfter( this.element );

 this.element.hide();
 this._createAutocomplete();
 this._createShowAllButton();
 },

 _createAutocomplete: function() {
 var selected = this.element.children( ":selected" ),
 value = selected.val() ? selected.text() : "";

 this.input = $( "<input>" )
 .appendTo( this.wrapper )
 .val( value )
 .attr( "title", "" )
 .addClass( "custom-combobox-input ui-widget ui-widget-content ui-state-default ui-corner-left" )
 .autocomplete({
 delay: 0,
 minLength: 0,
 source: $.proxy( this, "_source" )
 })
 .tooltip({
 tooltipClass: "ui-state-highlight"
 });

 this._on( this.input, {
 autocompleteselect: function( event, ui ) {
 ui.item.option.selected = true;
 this._trigger( "select", event, {
 item: ui.item.option
 });
 },

 autocompletechange: "_removeIfInvalid"
 });
 },

 _createShowAllButton: function() {
 var input = this.input,
 wasOpen = false;

 $( "<a>" )
 .attr( "tabIndex", -1 )
 .attr( "title", "Show All Items" )
 .tooltip()
 .appendTo( this.wrapper )
 .button({
 icons: {
 primary: "ui-icon-triangle-1-s"
 },
 text: false
 })
 .removeClass( "ui-corner-all" )
 .addClass( "custom-combobox-toggle ui-corner-right" )
 .mousedown(function() {
 wasOpen = input.autocomplete( "widget" ).is( ":visible" );
 })
 .click(function() {
 input.focus();

 // 如果已经可见则关闭
 if ( wasOpen ) {
 return;
 }

 // 传递空字符串作为搜索的值，显示所有的结果
 input.autocomplete( "search", "" );
 });
 },

 _source: function( request, response ) {
 var matcher = new RegExp( $.ui.autocomplete.escapeRegex(request.term), "i" );
 response( this.element.children( "option" ).map(function() {
 var text = $( this ).text();
 if ( this.value && ( !request.term || matcher.test(text) ) )
 return {
 label: text,
 value: text,
 option: this
 };
 }) );
 },

 _removeIfInvalid: function( event, ui ) {

 // 选择一项，不执行其他动作
 if ( ui.item ) {
 return;
 }

 // 搜索一个匹配（不区分大小写）
 var value = this.input.val(),
 valueLowerCase = value.toLowerCase(),
 valid = false;
 this.element.children( "option" ).each(function() {
 if ( $( this ).text().toLowerCase() === valueLowerCase ) {
 this.selected = valid = true;
 return false;
 }
 });

 // 找到一个匹配，不执行其他动作
 if ( valid ) {
 return;
 }

 // 移除无效的值
 this.input
 .val( "" )
 .attr( "title", value + " didn't match any item" )
 .tooltip( "open" );
 this.element.val( "" );
 this._delay(function() {
 this.input.tooltip( "close" ).attr( "title", "" );
 }, 2500 );
 this.input.data( "ui-autocomplete" ).term = "";
 },

 _destroy: function() {
 this.wrapper.remove();
 this.element.show();
 }
 });
 })( jQuery );

 $(function() {
 $( "#combobox" ).combobox();
 $( "#toggle" ).click(function() {
 $( "#combobox" ).toggle();
 });
 });
 </script>
</head>
<body>

<div class="ui-widget">
 <label>您喜欢的编程语言：</label>
 <select id="combobox">
 <option value="">请选择...</option>
 <option value="ActionScript">ActionScript</option>
 <option value="AppleScript">AppleScript</option>
 <option value="Asp">Asp</option>
 <option value="BASIC">BASIC</option>
 <option value="C">C</option>
 <option value="C++">C++</option>
 <option value="Clojure">Clojure</option>
 <option value="COBOL">COBOL</option>
 <option value="ColdFusion">ColdFusion</option>
 <option value="Erlang">Erlang</option>
 <option value="Fortran">Fortran</option>
 <option value="Groovy">Groovy</option>
 <option value="Haskell">Haskell</option>
 <option value="Java">Java</option>
 <option value="JavaScript">JavaScript</option>
 <option value="Lisp">Lisp</option>
 <option value="Perl">Perl</option>
 <option value="PHP">PHP</option>
 <option value="Python">Python</option>
 <option value="Ruby">Ruby</option>
 <option value="Scala">Scala</option>
 <option value="Scheme">Scheme</option>
 </select>
</div>
<button id="toggle">显示基础的选择框</button>


</body>
</html>
