自定义数据并显示
您可以使用自定义数据格式，并通过简单地重载默认的聚焦和选择行为来显示数据。
尝试键入 "j"，或者按向下箭头按键，即可得到一个项目列表。
<!doctype html>
<html lang="en">
<head>
 <meta charset="utf-8">
 <title>jQuery UI 自动完成（Autocomplete） - 自定义数据并显示</title>
 <link rel="stylesheet" href="//code.jquery.com/ui/1.10.4/themes/smoothness/jquery-ui.css">
 <script src="//code.jquery.com/jquery-1.9.1.js"></script>
 <script src="//code.jquery.com/ui/1.10.4/jquery-ui.js"></script>
 <link rel="stylesheet" href="http://jqueryui.com/resources/demos/style.css">
 <style>
 #project-label {
 display: block;
 font-weight: bold;
 margin-bottom: 1em;
 }
 #project-icon {
 float: left;
 height: 32px;
 width: 32px;
 }
 #project-description {
 margin: 0;
 padding: 0;
 }
 </style>
 <script>
 $(function() {
 var projects = [
 {
 value: "jquery",
 label: "jQuery",
 desc: "the write less, do more, JavaScript library",
 icon: "jquery_32x32.png"
 },
 {
 value: "jquery-ui",
 label: "jQuery UI",
 desc: "the official user interface library for jQuery",
 icon: "jqueryui_32x32.png"
 },
 {
 value: "sizzlejs",
 label: "Sizzle JS",
 desc: "a pure-JavaScript CSS selector engine",
 icon: "sizzlejs_32x32.png"
 }
 ];

 $( "#project" ).autocomplete({
 minLength: 0,
 source: projects,
 focus: function( event, ui ) {
 $( "#project" ).val( ui.item.label );
 return false;
 },
 select: function( event, ui ) {
 $( "#project" ).val( ui.item.label );
 $( "#project-id" ).val( ui.item.value );
 $( "#project-description" ).html( ui.item.desc );
 $( "#project-icon" ).attr( "src", "images/" + ui.item.icon );

 return false;
 }
 })
 .data( "ui-autocomplete" )._renderItem = function( ul, item ) {
 return $( "<li>" )
 .append( "<a>" + item.label + "<br>" + item.desc + "</a>" )
 .appendTo( ul );
 };
 });
 </script>
</head>
<body>

<div id="project-label">选择一个项目（请键入 "j"）：</div>
<img id="project-icon" src="images/transparent_1x1.png" class="ui-state-default" alt="">
<input id="project">
<input type="hidden" id="project-id">
<p id="project-description"></p>


</body>
</html>
查看演示
多个值
用法：键入一些字符，比如 "j"，可以看到相关的编程语言结果。选择一个值，然后继续键入字符来添加其他的值。
本实例演示如何使用 source 选项和一些事件来实现在一个单一的文本域输入多个自动完成的值。
<!doctype html>
<html lang="en">
<head>
 <meta charset="utf-8">
 <title>jQuery UI 自动完成（Autocomplete） - 多个值</title>
 <link rel="stylesheet" href="//code.jquery.com/ui/1.10.4/themes/smoothness/jquery-ui.css">
 <script src="//code.jquery.com/jquery-1.9.1.js"></script>
 <script src="//code.jquery.com/ui/1.10.4/jquery-ui.js"></script>
 <link rel="stylesheet" href="http://jqueryui.com/resources/demos/style.css">
 <script>
 $(function() {
 var availableTags = [
 "ActionScript",
 "AppleScript",
 "Asp",
 "BASIC",
 "C",
 "C++",
 "Clojure",
 "COBOL",
 "ColdFusion",
 "Erlang",
 "Fortran",
 "Groovy",
 "Haskell",
 "Java",
 "JavaScript",
 "Lisp",
 "Perl",
 "PHP",
 "Python",
 "Ruby",
 "Scala",
 "Scheme"
 ];
 function split( val ) {
 return val.split( /,\s*/ );
 }
 function extractLast( term ) {
 return split( term ).pop();
 }

 $( "#tags" )
 // 当选择一个条目时不离开文本域
 .bind( "keydown", function( event ) {
 if ( event.keyCode === $.ui.keyCode.TAB &&
 $( this ).data( "ui-autocomplete" ).menu.active ) {
 event.preventDefault();
 }
 })
 .autocomplete({
 minLength: 0,
 source: function( request, response ) {
 // 回到 autocomplete，但是提取最后的条目
 response( $.ui.autocomplete.filter(
 availableTags, extractLast( request.term ) ) );
 },
 focus: function() {
 // 防止在获得焦点时插入值
 return false;
 },
 select: function( event, ui ) {
 var terms = split( this.value );
 // 移除当前输入
 terms.pop();
 // 添加被选项
 terms.push( ui.item.value );
 // 添加占位符，在结尾添加逗号+空格
 terms.push( "" );
 this.value = terms.join( ", " );
 return false;
 }
 });
 });
 </script>
</head>
<body>

<div class="ui-widget">
 <label for="tags">编程语言：</label>
 <input id="tags" size="50">
</div>


</body>
</html>
