多个值，远程
用法：键入至少两个字符来获取鸟的名称。选择一个值，然后继续键入字符来添加其他的值。
本实例演示如何使用 source 选项和一些事件来实现在一个单一的文本域输入多个自动完成的值。
<!doctype html>
<html lang="en">
<head>
 <meta charset="utf-8">
 <title>jQuery UI 自动完成（Autocomplete） - 多个值，远程</title>
 <link rel="stylesheet" href="//code.jquery.com/ui/1.10.4/themes/smoothness/jquery-ui.css">
 <script src="//code.jquery.com/jquery-1.9.1.js"></script>
 <script src="//code.jquery.com/ui/1.10.4/jquery-ui.js"></script>
 <link rel="stylesheet" href="http://jqueryui.com/resources/demos/style.css">
 <style>
 .ui-autocomplete-loading {
 background: white url('/try/jqueryui/ui-anim_basic_16x16.gif') right center no-repeat;
 }
 </style>
 <script>
 $(function() {
 function split( val ) {
 return val.split( /,\s*/ );
 }
 function extractLast( term ) {
 return split( term ).pop();
 }

 $( "#birds" )
 // 当选择一个条目时不离开文本域
 .bind( "keydown", function( event ) {
 if ( event.keyCode === $.ui.keyCode.TAB &&
 $( this ).data( "ui-autocomplete" ).menu.active ) {
 event.preventDefault();
 }
 })
 .autocomplete({
 source: function( request, response ) {
 $.getJSON( "search.php", {
 term: extractLast( request.term )
 }, response );
 },
 search: function() {
 // 自定义最小长度
 var term = extractLast( this.value );
 if ( term.length < 2 ) {
 return false;
 }
 },
 focus: function() {
 // 防止在获得焦点时插入值
 return false;
 },
 select: function( event, ui ) {
 var terms = split( this.value );
 // 移除当前输入
 terms.pop();
 // 添加被选项
 terms.push( ui.item.value );
 // 添加占位符，在结尾添加逗号+空格
 terms.push( "" );
 this.value = terms.join( ", " );
 return false;
 }
 });
 });
 </script>
</head>
<body>

<div class="ui-widget">
 <label for="birds">鸟：</label>
 <input id="birds" size="50">
</div>


</body>
</html>
