远程 JSONP 数据源
用法：键入至少两个字符来获取鸟的名称。选择一个值，然后继续键入字符来添加其他的值。
本实例演示如何使用 jsonp 来获取数据。
<!doctype html>
<html lang="en">
<head>
 <meta charset="utf-8">
 <meta name="viewport" content="width=device-width, initial-scale=1">
 <title>jQuery UI Autocomplete - Remote JSONP datasource</title>
 <link rel="stylesheet" href="https://code.jquery.com/ui/1.12.1/themes/base/jquery-ui.css">

 <style>
 .ui-autocomplete-loading {
 background: white url('/try/jqueryui/ui-anim_basic_16x16.gif') right center no-repeat;
 }
 </style>
 <script src="https://code.jquery.com/jquery-1.12.4.js"></script>
 <script src="https://code.jquery.com/ui/1.12.1/jquery-ui.js"></script>
 <script>
 $( function() {
 function log( message ) {
 $( "<div>" ).text( message ).prependTo( "#log" );
 $( "#log" ).scrollTop( 0 );
 }

 $( "#birds" ).autocomplete({
 source: function( request, response ) {
 $.ajax( {
 url: "/try/jqueryui/search.php",
 dataType: "jsonp",
 data: {
 term: request.term
 },
 success: function( data ) {
 response( data );
 }
 } );
 },
 minLength: 2,
 select: function( event, ui ) {
 log( "Selected: " + ui.item.value + " aka " + ui.item.id );
 }
 } );
 } );
 </script>
</head>
<body>

<div class="ui-widget">
 <label for="birds">Birds: </label>
 <input id="birds">
</div>

<div class="ui-widget" style="margin-top:2em; font-family:Arial">
 Result:
 <div id="log" style="height: 200px; width: 300px; overflow: auto;" class="ui-widget-content"></div>
</div>


</body>
</html>
查看演示
远程数据源
当您在文本域中键入字符时，Autocomplete 部件给出建议结果。在本实例中，当您在文本域中至少键入两个字符时，将显示相关鸟的名称。
在本实例中，数据源是可返回 JSON 数据的服务器端脚本，通过一个简单的 source 选项来指定。另外，minLength 选项设置为 2，避免查询返回太多的结果，select 事件用于显示一些反馈。
<!doctype html>
<html lang="en">
<head>
 <meta charset="utf-8">
 <title>jQuery UI 自动完成（Autocomplete） - 远程数据源</title>
 <link rel="stylesheet" href="//code.jquery.com/ui/1.10.4/themes/smoothness/jquery-ui.css">
 <script src="//code.jquery.com/jquery-1.9.1.js"></script>
 <script src="//code.jquery.com/ui/1.10.4/jquery-ui.js"></script>
 <link rel="stylesheet" href="http://jqueryui.com/resources/demos/style.css">
 <style>
 .ui-autocomplete-loading {
 background: white url('/try/jqueryui/ui-anim_basic_16x16.gif') right center no-repeat;
 }
 </style>
 <script>
 $(function() {
 function log( message ) {
 $( "<div>" ).text( message ).prependTo( "#log" );
 $( "#log" ).scrollTop( 0 );
 }

 $( "#birds" ).autocomplete({
 source: "search.php",
 minLength: 2,
 select: function( event, ui ) {
 log( ui.item ?
 "Selected: " + ui.item.value + " aka " + ui.item.id :
 "Nothing selected, input was " + this.value );
 }
 });
 });
 </script>
</head>
<body>

<div class="ui-widget">
 <label for="birds">鸟：</label>
 <input id="birds">
</div>

<div class="ui-widget" style="margin-top:2em; font-family:Arial">
 结果：
 <div id="log" style="height: 200px; width: 300px; overflow: auto;" class="ui-widget-content"></div>
</div>


</body>
</html>
