 background: white url('/try/jqueryui/ui-anim_basic_16x16.gif') right center no-repeat;
 }
 </style>
 <script>
 $(function() {
 var cache = {};
 $( "#birds" ).autocomplete({
 minLength: 2,
 source: function( request, response ) {
 var term = request.term;
 if ( term in cache ) {
 response( cache[ term ] );
 return;
 }

 $.getJSON( "search.php", request, function( data, status, xhr ) {
 cache[ term ] = data;
 response( data );
 });
 }
 });
 });
 </script>
</head>
<body>

